#ifndef FW_GIT_HASH
#define FW_GIT_HASH "unknown"
#endif

#define TELEMETRY_RETRIES 3
#define TELEMETRY_RETRY_DELAY_MS 3000

WakeStats wakeStats = {};

// Escape characters that are special in line-protocol tag values
static String escapeTag(const String& in) {
  String out;
  out.reserve(in.length() + 4);
  for (size_t i = 0; i < in.length(); i++) {
    char c = in[i];
    if (c == ' ' || c == ',' || c == '=' || c == '\\') out += '\\';
    out += c;
  }
  return out;
}

// Non-finite floats would produce an invalid line, so swap in a sentinel
static float sane(float v) { return isfinite(v) ? v : -1.0f; }

void sendTelemetryWithRetries(void) {
  // Retrying can't help without wifi, so don't burn battery waiting
  if (!isWifiConnected()) {
    Serial.println("No wifi; skipping telemetry");
    return;
  }

  // One initial attempt plus TELEMETRY_RETRIES retries
  for (int attempt = 0; attempt <= TELEMETRY_RETRIES; attempt++) {
    if (sendTelemetry()) {
      Serial.println("Telemetry sent successfully");
      return;
    }

    if (attempt < TELEMETRY_RETRIES) {
      Serial.println("Telemetry failed; retrying in 3 seconds");
      delay(TELEMETRY_RETRY_DELAY_MS);
    }
  }

  Serial.printf("Telemetry failed after %d attempts; giving up\n", TELEMETRY_RETRIES + 1);
}

bool sendTelemetry() {
  if (!isWifiConnected()) return false;

  float solarV   = sane(getSolarVoltage());
  float batteryV = sane(getBatteryVoltage());
  int   mode     = (int)lastDisplayedMode;
  uint32_t staleSeconds = getTimeSinceLastUpdate();
  // Internal sensor, reads a few degrees above the enclosure air temperature
  float chipTempC = sane(temperatureRead());

  String ssid = escapeTag(WiFi.SSID());
  if (ssid.length() == 0) ssid = "unknown";

  char body[1024];
  int n = snprintf(body, sizeof(body),
    "diagnostics,device=%s,fw=%s "
      "solar_v=%.3f,battery_v=%.3f,rssi=%di,display_mode=%di,reset_reason=%di,"
      "time_since_last_update_s=%lu,heap_free=%ui,heap_min=%ui,"
      "wifi_failures_before_connect=%ui,"
      "wifi_connect_ms=%lui,ntp_ms=%lui,download_ms=%lui,refresh_ms=%lui,"
      "awake_ms=%lui,prev_awake_ms=%lui,"
      "display_result=%di,http_code=%di,chip_temp_c=%.1f,"
      "wake_count=%lui,crash_count=%lui,brownout_count=%lui,last_crash_reason=%di\n"
    "network,device=%s,ssid=%s connected=1i",
    GRAFANA_DEVICE, FW_GIT_HASH,
    solarV, batteryV, WiFi.RSSI(), mode, (int)esp_reset_reason(),
    (unsigned long)staleSeconds,
    (unsigned)ESP.getFreeHeap(), (unsigned)ESP.getMinFreeHeap(),
    (unsigned)wifiFailuresBeforeConnect,
    (unsigned long)wakeStats.wifiConnectMs, (unsigned long)wakeStats.ntpMs,
    (unsigned long)wakeStats.downloadMs, (unsigned long)wakeStats.refreshMs,
    (unsigned long)millis(), (unsigned long)previousWakeAwakeMs,
    (int)wakeStats.displayResult, wakeStats.httpCode, chipTempC,
    (unsigned long)resetStats.wakeCount, (unsigned long)resetStats.crashCount,
    (unsigned long)resetStats.brownoutCount, resetStats.lastCrashReason,
    GRAFANA_DEVICE, ssid.c_str());

  if (n < 0 || n >= (int)sizeof(body)) {
    Serial.println("Telemetry body truncated");
    return false;
  }

  WiFiClientSecure client;
  client.setInsecure();  // same trade-off as discussed earlier
  HTTPClient http;
  http.setTimeout(5000);
  http.begin(client, INFLUX_DB_URL);
  http.setAuthorization(GC_USER, GC_TOKEN);
  http.addHeader("Content-Type", "text/plain");
  int code = http.POST((uint8_t*)body, n);
  http.end();

  bool ok = (code >= 200 && code < 300);
  if (!ok) Serial.printf("Telemetry failed: %d\n", code);
  return ok;
}